import java.util.*;

public class Example {
    static int fee(int age) {
        if (age < 0) throw new IllegalArgumentException("age < 0");
        return age < 5 ? 0 : age < 18 ? 50 : age < 60 ? 200 : 100;
    }

    static void equal(Object expected, Object actual) {
        if (!Objects.equals(expected, actual))
            throw new AssertionError("expected <" + expected + "> but got <" + actual + ">");
    }

    public static void main(String[] args) {
        Map<String, Runnable> tests = new LinkedHashMap<>();
        tests.put("under 5 is free", () -> equal(0, fee(4)));
        tests.put("age 18 is an adult", () -> equal(200, fee(18)));
        tests.put("age 60 gets the discount", () -> equal(100, fee(60)));
        tests.put("negative age is rejected", () -> {
            try { fee(-1); throw new AssertionError("no exception"); }
            catch (IllegalArgumentException expected) { }
        });

        int passed = 0;
        for (var t : tests.entrySet()) {
            try { t.getValue().run(); passed++; }
            catch (AssertionError e) { System.out.println("FAIL " + t.getKey() + ": " + e.getMessage()); }
        }
        System.out.println(passed + " of " + tests.size() + " passed");
    }
}

