import java.util.Objects;

public class Assert {
    public static void equal(Object expected, Object actual) {
        if (!Objects.equals(expected, actual)) {   // null-safe
            throw new AssertionError("expected <" + expected + "> but got <" + actual + ">");
        }
    }

    public static void isTrue(boolean condition, String message) {
        if (!condition) throw new AssertionError(message);
    }

    public static void expectThrows(Class<? extends Throwable> type, Runnable code) {
        try {
            code.run();
        } catch (Throwable t) {
            if (type.isInstance(t)) return;   // the right kind (or a subclass): pass
            throw new AssertionError("expected " + type.getSimpleName() + " but got " + t.getClass().getSimpleName());
        }
        throw new AssertionError("expected " + type.getSimpleName() + " but nothing was thrown");
    }
}

