import java.util.function.IntUnaryOperator;

public class Fees {
    public static int fee(int age) {
        if (age < 0) throw new IllegalArgumentException("age can't be negative");
        if (age < 5) return 0;
        if (age < 18) return 50;
        if (age < 60) return 200;
        return 100;
    }

    // Both sides of every boundary, plus the bad input.
    public static boolean checkFee(IntUnaryOperator f) {
        return gives(f, 0, 0) && gives(f, 4, 0)
            && gives(f, 5, 50) && gives(f, 17, 50)
            && gives(f, 18, 200) && gives(f, 59, 200)
            && gives(f, 60, 100) && gives(f, 90, 100)
            && rejects(f, -1);
    }

    static boolean gives(IntUnaryOperator f, int age, int want) {
        try {
            return f.applyAsInt(age) == want;
        } catch (RuntimeException e) {
            return false;   // crashing on a valid age is a bug too
        }
    }

    static boolean rejects(IntUnaryOperator f, int age) {
        try {
            f.applyAsInt(age);
            return false;   // it should have thrown
        } catch (IllegalArgumentException e) {
            return true;
        }
    }
}

