import java.util.*;

public class Runner {
    public static String runAll(Map<String, Runnable> tests) {
        int passed = 0;
        List<String> failed = new ArrayList<>();
        for (var e : tests.entrySet()) {
            try {
                e.getValue().run();
                passed++;
            } catch (AssertionError | RuntimeException ex) {   // a failure or a crash
                failed.add(e.getKey());
            }
        }
        String report = tests.size() + " run, " + passed + " passed";
        if (!failed.isEmpty()) report += ", " + failed.size() + " failed: " + String.join(", ", failed);
        return report;
    }
}
